mapper.select:
SELECT t1.id, t1.ledger_id, t1.account_id, t3.name AS account_name, t1.category_id, t4.name AS category_name, t1.amount, t1.type, t1.transaction_date, t1.note, t1.is_excluded, t1.create_time FROM jz_transactions t1 LEFT JOIN jz_accounts t3 ON t3.id = t1.account_id AND t3.is_deleted = 0 LEFT JOIN jz_categories t4 ON t4.id = t1.category_id AND t4.is_deleted = 0 WHERE t1.is_deleted = 0
AND t1.user_id = #{queryParams.userId}
AND t1.ledger_id = #{queryParams.ledgerId}
AND t1.account_id = #{queryParams.accountId}
AND t1.category_id = #{queryParams.categoryId}
AND t1.type = #{queryParams.type}
AND t1.transaction_date BETWEEN
${date}
AND t1.note LIKE CONCAT('%', #{queryParams.note}, '%')
ORDER BY t1.transaction_date DESC, t1.create_time DESC
